{
  "originalFormula": "R_{substrate} = 3-10 \, \\text{ohm-cm}",
  "genericFormula": "R_{substrate} = R_{min} - R_{max} \, \\text{ohm-cm}",
  "description": "Esta fórmula representa a resistividade de um substrato semicondutor, que é uma medida de quão bem o material conduz eletricidade. A resistividade é expressa em ohm-centímetros e indica a capacidade do substrato de permitir a passagem de corrente elétrica.",
  "concepts": [
    "Resistividade",
    "Condutividade elétrica",
    "Semicondutores"
  ],
  "symbols": [
    {
      "symbol": "R_{substrate}",
      "description": "Representa a resistividade do substrato semicondutor, que é a propriedade do material que determina sua capacidade de conduzir corrente elétrica."
    },
    {
      "symbol": "3-10",
      "description": "Indica o intervalo de valores da resistividade, onde 3 é o valor mínimo e 10 é o valor máximo, ambos em ohm-centímetros."
    }
  ]
}

{
  "originalFormula": "d_{buried} = 3 \, \\mu m",
  "genericFormula": "d_{buried} = d",
  "description": "Esta fórmula representa a profundidade de uma camada enterrada em um material semicondutor, medida em micrômetros. A profundidade é uma característica importante em aplicações de dispositivos semicondutores, pois influencia o desempenho e as propriedades elétricas do material.",
  "concepts": [
    "Profundidade de camadas em semicondutores",
    "Estrutura de dispositivos semicondutores",
    "Propriedades elétricas de materiais"
  ],
  "symbols": [
    {
      "symbol": "d_{buried}",
      "description": "Representa a profundidade da camada enterrada em um material semicondutor."
    },
    {
      "symbol": "\\mu m",
      "description": "Representa a unidade de medida micrômetro, que é um milionésimo de metro."
    }
  ]
}

{
  "originalFormula": "R_{epitaxial} = 0.1 - 1 \, \\text{ohm-cm}",
  "genericFormula": "R_{epitaxial} = a - b \, \\text{ohm-cm}",
  "description": "Esta fórmula representa a resistência elétrica de um material epitaxial, que é uma camada de material depositada sobre um substrato. A resistência é uma medida de quão difícil é para a corrente elétrica passar através do material. Neste caso, a resistência varia entre dois valores, indicando que o material pode ter diferentes características dependendo de sua composição ou estrutura.",
  "concepts": [
    "Resistência elétrica",
    "Materiais semicondutores",
    "Epitaxia"
  ],
  "symbols": [
    {
      "symbol": "R_{epitaxial}",
      "description": "Representa a resistência elétrica do material epitaxial, que é a quantidade que mede a oposição ao fluxo de corrente elétrica através desse material."
    },
    {
      "symbol": "a",
      "description": "Um valor numérico que representa o limite inferior da resistência do material epitaxial, indicando a menor resistência que pode ser encontrada."
    },
    {
      "symbol": "b",
      "description": "Um valor numérico que representa o limite superior da resistência do material epitaxial, indicando a maior resistência que pode ser encontrada."
    }
  ]
}

{
  "originalFormula": "d_{epitaxial} = 0.5 - 5 \, \\mu m",
  "genericFormula": "d_{epitaxial} = a - b \, \\mu m",
  "description": "Esta fórmula representa a espessura de uma camada epitaxial, que é uma camada de material depositada sobre um substrato, onde a espessura é determinada pela diferença entre um valor constante e um valor que pode variar.",
  "concepts": [
    "Camadas epitaxiais",
    "Deposição de materiais",
    "Espessura de filmes finos"
  ],
  "symbols": [
    {
      "symbol": "d_{epitaxial}",
      "description": "Representa a espessura da camada epitaxial em micrômetros."
    },
    {
      "symbol": "a",
      "description": "Um valor constante que representa a espessura inicial ou base da camada epitaxial."
    },
    {
      "symbol": "b",
      "description": "Um valor que pode variar, representando a quantidade que é subtraída da espessura base."
    }
  ]
}
